<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { Search, Refresh, ArrowRight, Box } from '@element-plus/icons-vue'; import { enterpriseApi } from '@/api/enterprise'; import type { UpstreamBatch, UpstreamEnterprise } from '@/types/domain'; import PageHeader from '@/components/PageHeader.vue'; import EmptyState from '@/components/EmptyState.vue';
const enterprises = ref<UpstreamEnterprise[]>([]); const batches = ref<UpstreamBatch[]>([]); const enterpriseLoading = ref(false); const batchLoading = ref(false); const selectedId = ref<string>(); const query = reactive({ enterpriseName: '', batchNo: '' })
async function loadEnterprises() { enterpriseLoading.value = true; try { const result = await enterpriseApi.upstreamEnterprises({ current: 1, size: 50, enterpriseName: query.enterpriseName }); enterprises.value = result.records } catch (error) { ElMessage.error(error instanceof Error ? error.message : '上游企业加载失败') } finally { enterpriseLoading.value = false } }
async function selectEnterprise(id: string) { selectedId.value = id; batchLoading.value = true; try { const result = await enterpriseApi.upstreamBatches({ current: 1, size: 50, upstreamEnterpriseId: id, batchNo: query.batchNo }); batches.value = result.records } catch (error) { ElMessage.error(error instanceof Error ? error.message : '上游批号加载失败') } finally { batchLoading.value = false } }
onMounted(loadEnterprises)
</script>
<template><div class="upstream-view"><PageHeader eyebrow="UPSTREAM NETWORK" title="上游数据" description="查看已发布的上游企业与产品批号，为新批次建立可信来源"><template #default><el-button :icon="Refresh" @click="loadEnterprises">刷新</el-button></template></PageHeader><div class="upstream-layout"><section class="data-panel upstream-enterprises"><div class="data-panel__head"><div><strong>上游企业</strong><span>{{ enterprises.length }} 家可选</span></div></div><div class="upstream-search"><el-input v-model="query.enterpriseName" clearable placeholder="搜索企业" @keyup.enter="loadEnterprises"><template #prefix><el-icon><Search /></el-icon></template></el-input></div><div v-loading="enterpriseLoading" class="upstream-list"><button v-for="enterprise in enterprises" :key="enterprise.id" class="upstream-item" :class="{ 'is-selected': selectedId === enterprise.id }" @click="selectEnterprise(enterprise.id)"><span class="upstream-item__avatar"><el-icon><Box /></el-icon></span><span><strong>{{ enterprise.enterpriseName }}</strong><small>{{ enterprise.enterpriseTypeName }} · {{ enterprise.provinceName }}{{ enterprise.cityName }}</small></span><el-icon><ArrowRight /></el-icon></button><EmptyState v-if="!enterprises.length && !enterpriseLoading" title="暂无可用企业" /></div></section><section class="data-panel upstream-batches"><div class="data-panel__head"><div><strong>已发布批号</strong><span>{{ selectedId ? '选择一条批号用于建立来源' : '先选择一家上游企业' }}</span></div></div><div v-if="selectedId" class="upstream-search"><el-input v-model="query.batchNo" clearable placeholder="搜索上游批号" @keyup.enter="selectEnterprise(selectedId!)" /></div><div v-loading="batchLoading" class="upstream-list"><button v-for="batch in batches" :key="batch.id" class="upstream-batch"><span><strong>{{ batch.batchNo }}</strong><small>{{ batch.productVariety || '品种未填写' }} · {{ batch.publishTime || '-' }}</small></span><el-button text type="primary">查看</el-button></button><EmptyState v-if="selectedId && !batches.length && !batchLoading" title="暂无已发布批号" description="该企业当前没有符合条件的已发布批号" /><div v-if="!selectedId" class="upstream-placeholder"><span>01</span><strong>选择上游企业</strong><p>这里会展示该企业当前可被追溯的已发布产品批号。</p></div></div></section></div></div></template>
